#!/bin/bash

# This script fixes the file ownership issues that may appear when manipulating, on the development machine, files generated by the 'root' user of the Docker container.
#
# Usage: bash fix-permission-issues.bash

################################################################################

# List the Catkin workspaces of the core, the platform, and the active extensions.
source ${OPENROSDE_CONTAINER_ROOT_DIR}/scripts/load-extension-paths.bash ${OPENROSDE_CONTAINER_ROOT_DIR}

# Find files and directories owned by 'root' in the 'src/' directories of the Catkin workspaces and change ownership to current user and group IDs.
for OPENROSDE_CATKIN_WS in "${OPENROSDE_CATKIN_WORKSPACE_DIRS[@]}"; do
  find ${OPENROSDE_CATKIN_WS}/src/ -user root -print -exec chown ${OPENROSDE_USER_ID}:${OPENROSDE_GROUP_ID} {} \;
done
